import{_ as i,a0 as l,w as d,s as p,ao as s,I as a,x as t,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何从Linux命令行截屏 | LCTT x X-CMD","titleTemplate":false,"description":"如何从Linux命令行截屏 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从Linux命令行截屏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从Linux命令行截屏 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to take a screenshot from the command line on Linux","title":"如何从Linux命令行截屏","tag":"201406","desc":""},"relativePath":"201406/How to take a screenshot from the command line on Linux.md","filePath":"[post].md"}'),m={name:"201406/How to take a screenshot from the command line on Linux.md"};function c(u,e,h,x,f,_){const o=l("Link");return d(),p("div",null,[e[14]||(e[14]=s(`<h1 id="如何从linux命令行截屏" tabindex="-1">如何从Linux命令行截屏 <a class="header-anchor" href="#如何从linux命令行截屏" aria-label="Permalink to “如何从Linux命令行截屏”">​</a></h1><p>Linux上有着许多不同口味儿的截屏工具，包括桌面环境专用的截屏程序（如： KDE里面的KSnapshot，GNOME里面的gnome-screenshot，Xfce的Screenshooter），或者是通用的截屏程序（如 Shutter）。而Scort（&quot;SCReen shOT&quot;的缩写）是最独一无二的截屏工具之一，它是一个<strong>命令行截屏工具</strong>。虽然它的界面十分简约，但Scrot在功能上和其它专用的基于GUI的屏幕捕获工具一样强大。举个例子，Scrot支持延时截屏，截屏调整品质/大小，命令行传递等功能。如果你是那些热衷命令行的爱好者之一，Scrot应该是你加入兵器库中的又一实用工具。在这个教程中，我将会描述<strong>如何在命令行中用Scrot截屏</strong>。</p><h3 id="在linux中安装scrot" tabindex="-1">在Linux中安装Scrot <a class="header-anchor" href="#在linux中安装scrot" aria-label="Permalink to “在Linux中安装Scrot”">​</a></h3><p>在 Debian，Ubuntu 或 Linux Mint 上安装Scrot：</p><pre><code>$ sudo apt-get install scrot
</code></pre><p>在 Fedora 上安装Scrot：</p><pre><code>$ sudo yum install scrot
</code></pre><p>要在CentOS上安装Scrot，你可以按照下列步骤从源码编译：</p>`,8)),a("p",null,[e[1]||(e[1]=t("首先",-1)),r(o,{href:"http://xmodulo.com/2013/01/how-to-set-up-rpmforge-repoforge-repository-on-centos.html"},{default:n(()=>[...e[0]||(e[0]=[t("在CentOS上启用Repoforge",-1)])]),_:1}),e[2]||(e[2]=t("，然后使用下列命令：",-1))]),e[15]||(e[15]=s(`<pre><code>$ sudo yum install giblib-devel
$ wget http://linuxbrit.co.uk/downloads/scrot-0.8.tar.gz
$ tar xvfvz scrot-0.8.tar.gz
$ cd scrot-0.8
$ ./configure
$ make
$ sudo make install
</code></pre><h3 id="用scrot截屏" tabindex="-1">用Scrot截屏 <a class="header-anchor" href="#用scrot截屏" aria-label="Permalink to “用Scrot截屏”">​</a></h3><p>在这个教程的下面的部分，我会描述如何通过几种不同方法用Scrot截屏。</p><h4 id="_1-截下整个桌面" tabindex="-1">1. 截下整个桌面 <a class="header-anchor" href="#_1-截下整个桌面" aria-label="Permalink to “1. 截下整个桌面”">​</a></h4><p>截取整个桌面十分简单。只需运行Scrot命令，不需要任何参数，然后它会保存一张整个桌面的截屏，以(日期标记).png的文件形式保存在当前文件目录下。</p><pre><code>$ scrot
</code></pre><p>你也可以指定保存目标文件夹和截图文件名。</p><pre><code>$ scrot ~/Pictures/my_desktop.png
</code></pre><h4 id="_2-截取特定窗口或矩形区域" tabindex="-1">2. 截取特定窗口或矩形区域 <a class="header-anchor" href="#_2-截取特定窗口或矩形区域" aria-label="Permalink to “2. 截取特定窗口或矩形区域”">​</a></h4><p>Scrot允许你在桌面选择一个特定的窗口或定义一个矩形区域来截图。使用下列命令来实现：</p><pre><code>$ scrot -s
</code></pre><p>运行这个命令后，继续用你的鼠标单击任意窗口或画出一个矩形，它能够触发对选定窗口/区域的屏幕截取。（LCTT译注，还要使用鼠标，伐快乐）</p><p>有时候你选定的区域或窗口可能会被桌面的其它窗口部分遮挡。在这种情况下，你在截屏前需要一点时间来清理那个部分。那正是延迟截屏能够帮到你的，就像下面所描述的那样。</p><h4 id="_3-延迟截屏" tabindex="-1">3. 延迟截屏 <a class="header-anchor" href="#_3-延迟截屏" aria-label="Permalink to “3. 延迟截屏”">​</a></h4><p>延迟截取在各种情况下都很实用。就在截图前，你可能想要移动一下窗口，激活一下菜单，或是触发特定时间（如通知）等等。 使用“-d N”参数，我们可以将截屏进程延迟N秒。</p><pre><code>$ scrot -s -d 5
</code></pre><h4 id="_4-调整截屏质量" tabindex="-1">4. 调整截屏质量 <a class="header-anchor" href="#_4-调整截屏质量" aria-label="Permalink to “4. 调整截屏质量”">​</a></h4><p>你可以在1到100的范围内调整截取的图像质量（数字越大质量越高）。默认质量设置为75。</p><pre><code>$ scrot -q 50
</code></pre><h4 id="_5-调整截屏尺寸" tabindex="-1">5. 调整截屏尺寸 <a class="header-anchor" href="#_5-调整截屏尺寸" aria-label="Permalink to “5. 调整截屏尺寸”">​</a></h4><p>你可以在1到100的范围内调整截取的图像尺寸（数字越大尺寸越大）。减小截屏的尺寸到原图的10％：</p><pre><code>$ scrot -t 10
</code></pre><h4 id="_6-将截取的截屏传递给其它命令" tabindex="-1">6. 将截取的截屏传递给其它命令 <a class="header-anchor" href="#_6-将截取的截屏传递给其它命令" aria-label="Permalink to “6. 将截取的截屏传递给其它命令”">​</a></h4><p>Scrot允许你发送保存的截屏图像给任意一个命令作为它们的输入。这个选项在你想对截屏图像做任意后期处理的时候十分实用。截屏的文件名/路径跟随于“$f”字符串之后。</p><pre><code>$ scrot -e &#39;mv $f ~/screenshots&#39;
</code></pre><hr>`,26)),a("p",null,[e[4]||(e[4]=t("via: ",-1)),r(o,{href:"http://xmodulo.com/2014/05/take-screenshot-command-line-linux.html"},{default:n(()=>[...e[3]||(e[3]=[t("http://xmodulo.com/2014/05/take-screenshot-command-line-linux.html",-1)])]),_:1})]),a("p",null,[e[7]||(e[7]=t("译者：",-1)),r(o,{href:"https://github.com/alim0x"},{default:n(()=>[...e[5]||(e[5]=[t("alim0x",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创翻译，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const L=i(m,[["render",c]]);export{b as __pageData,L as default};
